use super::{FunderNameFeatures, NameStatus};

fn features(name: &str) -> FunderNameFeatures {
    FunderNameFeatures::from_name(Some(name))
}

#[test]
fn keeps_raw_names_and_parallel_features_without_erasing_geography() {
    let name = features("  Ｍｒ.  James O’Brien-Smith  ");
    assert_eq!(
        name.name_raw.as_deref(),
        Some("  Ｍｒ.  James O’Brien-Smith  ")
    );
    assert_eq!(
        name.name_normalized.as_deref(),
        Some("mr. james o’brien-smith")
    );
    assert_eq!(name.name_tokens.as_deref(), Some("mr james obrien smith"));
    assert_eq!(name.person_core.as_deref(), Some("james obrien smith"));
    assert_eq!(name.person_initials.as_deref(), Some("jos"));
    assert_eq!(
        features("Friends of Sinn Féin Canada")
            .name_accent_folded
            .as_deref(),
        Some("friends of sinn fein canada")
    );
    assert_eq!(
        features("BJD (GB) Limited").organisation_core.as_deref(),
        Some("bjd gb")
    );
    assert_eq!(
        features("BJD (GB) Limited").name_normalized.as_deref(),
        Some("bjd (gb) limited")
    );
    assert_eq!(
        features("U.K. Example LTD.").name_tokens.as_deref(),
        Some("uk example ltd")
    );
    assert_eq!(
        features("Example (U.K.), Ltd.").name_tokens.as_deref(),
        Some("example uk ltd")
    );
    assert_eq!(
        features("Communication Workers’ Union")
            .name_tokens
            .as_deref(),
        Some("communication workers union")
    );
}

#[test]
fn extracts_only_explicit_aliases_and_keeps_primary_and_full_names() {
    let name = features("CSC Computer Sciences Limited (Trading as DXC Technology Ltd) (UK)");
    assert_eq!(name.explicit_aliases, ["DXC Technology Ltd"]);
    assert_eq!(name.alias_normalized, ["dxc technology ltd"]);
    assert_eq!(
        name.primary_name_normalized.as_deref(),
        Some("csc computer sciences limited (uk)")
    );
    assert_eq!(
        name.parenthetical_text,
        ["Trading as DXC Technology Ltd", "UK"]
    );
    assert!(
        name.name_tokens
            .unwrap()
            .contains("trading as dxc technology")
    );
    assert_eq!(
        features("CSC Computer Sciences Limited (Trading as DXC Technology Ltd)")
            .organisation_core
            .as_deref(),
        Some("csc computer sciences")
    );
    for (raw, expected) in [
        (
            "British Academy of Songwriters, Composers and Authors, trading as The Ivors Academy",
            "The Ivors Academy",
        ),
        (
            "Fletchers Solicitors Limited t/a Fletchers Solicitors",
            "Fletchers Solicitors",
        ),
        ("Pierce Protocols Limited trading as Heni", "Heni"),
    ] {
        assert_eq!(features(raw).explicit_aliases, [expected]);
    }
    assert!(
        features("MPM Connect Ltd (a company controlled by Peter Hearn)")
            .explicit_aliases
            .is_empty()
    );
    assert!(
        features("Example (sponsored by Other)")
            .explicit_aliases
            .is_empty()
    );
}

#[test]
fn validates_acronyms_and_records_literal_ambiguity_evidence() {
    let aslef = features("ASLEF (Associated Society of Locomotive Engineers and Firemen)");
    assert_eq!(aslef.explicit_acronym.as_deref(), Some("aslef"));
    assert_eq!(
        aslef.acronym_expansion_normalized.as_deref(),
        Some("associated society of locomotive engineers and firemen")
    );
    assert_eq!(
        features("Associated Society of Locomotive Engineers and Firemen (ASLEF)")
            .explicit_acronym
            .as_deref(),
        Some("aslef")
    );
    assert_eq!(features("BJD (GB) Limited").explicit_acronym, None);
    assert!(features("Alan Milburn & Ruth Briel").has_conjunction);
    assert!(features("Unite the Union (UK").has_unbalanced_parentheses);
    assert!(features("Unite) the Union").has_unbalanced_parentheses);
    assert!(!features("Unite (the Union)").has_unbalanced_parentheses);
    assert_eq!(
        features("Sir Trevor Chinn").person_core.as_deref(),
        Some("trevor chinn")
    );
    assert_eq!(
        features("Lord Michael Farmer").person_core.as_deref(),
        Some("michael farmer")
    );
    assert_eq!(
        features("Example Limited Edition")
            .organisation_core
            .as_deref(),
        Some("example limited edition")
    );
}

#[test]
fn withholds_matching_features_for_missing_and_confidential_names() {
    for raw in [None, Some(""), Some(" \t ")] {
        let name = FunderNameFeatures::from_name(raw);
        assert_eq!(name.name_status, NameStatus::Missing);
        assert!(name.name_normalized.is_none());
    }
    let name = features(" Confidential ");
    assert_eq!(name.name_status, NameStatus::Withheld);
    assert_eq!(name.name_raw.as_deref(), Some(" Confidential "));
    assert!(name.name_token_key.is_none());
    assert_eq!(
        features("Confidential Company Ltd").name_status,
        NameStatus::Present
    );
    assert_eq!(
        features("National  Liberal Club")
            .name_normalized
            .as_deref(),
        Some("national liberal club")
    );
    assert_eq!(
        features("Labour Together Limited").organisation_core,
        features("LABOUR TOGETHER LTD.").organisation_core
    );
    assert_eq!(
        features("The Club Club").name_token_key.as_deref(),
        Some("club club the")
    );
}
use super::*;

fn observation(
    id: u32,
    name: Option<&str>,
    address: Option<&str>,
    kind: Option<&str>,
    company: Option<&str>,
) -> Observation {
    Observation {
        funder_id: serde_json::from_value(serde_json::json!(format!(
            "00000000-0000-0000-0000-000000000001/{id}/1/declaration/donor"
        )))
        .unwrap(),
        member_id: "00000000-0000-0000-0000-000000000001".into(),
        declaration_id: id,
        register_id: 1,
        role: FunderRole::Donor,
        source_scope: "declaration".into(),
        source_pointer: "/versions/0/fields".into(),
        funding_entry_id: None,
        funding_ordinal: None,
        donor_kind: kind.map(str::to_owned),
        donor_company_number: company.map(str::to_owned),
        name_raw: name.map(str::to_owned),
        name_normalized: name.map(str::to_owned),
        organisation_core: name.map(str::to_owned),
        alias_normalized: Vec::new(),
        address_normalized: address.map(str::to_owned),
        address_match_quality: AddressMatchQuality::from_normalized(address),
    }
}
fn input(observations: Vec<Observation>) -> ResolutionInput {
    ResolutionInput::new(observations, Vec::new(), BTreeMap::new()).unwrap()
}
fn resolve(input: &ResolutionInput, probability: f64) -> ResolvedDeclarations {
    let scoring = input.scoring_input(100);
    let pairs = scoring
        .rows
        .iter()
        .enumerate()
        .flat_map(|(index, left)| {
            scoring.rows[index + 1..]
                .iter()
                .map(move |right| ScoredPair {
                    left: left.key.clone(),
                    right: right.key.clone(),
                    probability,
                    name_level: 2,
                    address_level: 1,
                })
        })
        .collect();
    let scored =
        ScoredPairs::checked(pairs, serde_json::json!({"calibrated":false}), &scoring).unwrap();
    ResolvedDeclarations::from_scored(input, &scoring, scored, "test-run").unwrap()
}
fn payer(mut observation: Observation) -> Observation {
    observation.role = FunderRole::Payer;
    observation.donor_kind = None;
    observation.donor_company_number = None;
    observation.funder_id = serde_json::from_value(serde_json::json!(
        observation.funder_id.as_str().replace("/donor", "/payer")
    ))
    .unwrap();
    observation
}
#[test]
fn exact_donor_names_link_without_address_or_threshold() {
    for addresses in [
        (None, None),
        (Some("1 road"), Some("2 road")),
        (Some("london"), None),
    ] {
        let result = resolve(
            &input(vec![
                observation(
                    1,
                    Some("gary lubner"),
                    addresses.0,
                    Some("Individual"),
                    None,
                ),
                observation(
                    2,
                    Some("gary lubner"),
                    addresses.1,
                    Some("Individual"),
                    None,
                ),
            ]),
            0.01,
        );
        assert_eq!(
            result.observations[0].identity_id,
            result.observations[1].identity_id
        );
        assert!(
            result
                .observations
                .iter()
                .all(|row| matches!(row.identity_basis, IdentityBasis::DonorNameLink))
        );
        assert_eq!(result.pairs[0].probability.to_bits(), 0.01_f64.to_bits());
        assert!(matches!(result.pairs[0].reason, PairReason::ExactDonorName));
        assert_eq!(result.pairs[0].disposition, PairDisposition::Accepted);
    }
}
#[test]
fn fuzzy_missing_and_other_role_names_do_not_use_donor_rule() {
    for (left, right) in [
        (
            observation(1, Some("john smith"), None, None, None),
            observation(2, Some("jon smith"), None, None, None),
        ),
        (
            observation(1, None, None, None, None),
            observation(2, None, None, None, None),
        ),
        (
            observation(1, Some("john smith"), None, None, None),
            payer(observation(2, Some("john smith"), None, None, None)),
        ),
    ] {
        let result = resolve(&input(vec![left, right]), 0.9999);
        assert!(
            result
                .pairs
                .iter()
                .all(|pair| pair.disposition == PairDisposition::Review)
        );
        assert!(result.observations.iter().all(|row| matches!(
            row.identity_basis,
            IdentityBasis::ProvisionalSingleton | IdentityBasis::Unresolved
        )));
    }
}

#[test]
fn extracted_hsbc_name_and_punctuation_normalized_address_link_across_roles() {
    let mut ceo = observation(
        1,
        Some("HSBC UK (Ian Stuart, CEO)"),
        Some("1 Centenary Square, Birmingham, B1 1HQ"),
        Some("Company"),
        None,
    );
    ceo.name_raw = Some("HSBC UK (Ian Stuart, CEO)".into());
    let mut bank = observation(
        2,
        Some("HSBC UK Bank plc"),
        Some("1 Centenary Square Birmingham B1 1HQ"),
        Some("Company"),
        None,
    );
    bank.name_raw = Some("HSBC UK Bank plc".into());
    let payer_observation = payer(bank);
    let result = resolve(&input(vec![ceo, payer_observation]), 0.08);
    assert_eq!(
        result.observations[0].identity_id,
        result.observations[1].identity_id
    );
    assert!(result.pairs.iter().any(|pair| {
        pair.disposition == PairDisposition::Accepted
            && matches!(pair.reason, PairReason::ExtractedNameEvidence)
    }));
}

